values
('bmlt-mycovirology1-practice-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"Which stain is commonly used to demonstrate fungal elements in tissue sections?","translation":"","options":["Periodic acid–Schiff (PAS)","Gram stain only","Albert stain","Leishman stain"],"correctIndex":0,"explanation":"PAS highlights fungal cell walls in tissue. नेपाली: Tissue मा fungus देखाउन PAS stain उपयोगी हुन्छ।","explanationNe":"Tissue मा fungus देखाउन PAS stain उपयोगी हुन्छ।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
('bmlt-mycovirology1-practice-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"Which medium is commonly used for primary isolation of many pathogenic fungi?","translation":"","options":["Sabouraud dextrose agar","MacConkey agar","XLD agar","CLED agar"],"correctIndex":0,"explanation":"Sabouraud dextrose agar supports fungal growth and may contain antibiotics. नेपाली: धेरै fungus culture गर्न Sabouraud agar प्रयोग हुन्छ।","explanationNe":"धेरै fungus culture गर्न Sabouraud agar प्रयोग हुन्छ।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
('bmlt-mycovirology1-practice-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"Which fungal structure is classically seen in Candida albicans germ tube test?","translation":"","options":["Germ tube","Spherule","Broad aseptate hypha","Sporangium"],"correctIndex":0,"explanation":"C. albicans commonly forms germ tubes in serum at 37°C. नेपाली: Candida albicans germ tube positive हुन सक्छ।","explanationNe":"Candida albicans germ tube positive हुन सक्छ।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
('bmlt-mycovirology1-practice-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"Which fungus is associated with encapsulated yeast cells and can be demonstrated by India ink in CSF?","translation":"","options":["Cryptococcus neoformans","Aspergillus fumigatus","Trichophyton rubrum","Candida tropicalis"],"correctIndex":0,"explanation":"Cryptococcus has a prominent capsule; India ink may show a halo. नेपाली: Cryptococcus को capsule India ink मा देखिन सक्छ।","explanationNe":"Cryptococcus को capsule India ink मा देखिन सक्छ।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
('bmlt-mycovirology1-practice-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"Which fungal genus commonly shows septate hyphae with acute-angle branching?","translation":"","options":["Aspergillus","Mucor","Rhizopus","Candida"],"correctIndex":0,"explanation":"Aspergillus typically has septate hyphae with acute-angle branching. नेपाली: Aspergillus मा acute-angle branching septate hyphae देखिन्छ।","explanationNe":"Aspergillus मा acute-angle branching septate hyphae देखिन्छ।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
('bmlt-mycovirology1-practice-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"Broad, ribbon-like, pauciseptate hyphae are characteristic of?","translation":"","options":["Mucorales","Aspergillus","Dermatophytes","Candida"],"correctIndex":0,"explanation":"Mucorales often show broad, ribbon-like pauciseptate hyphae. नेपाली: Mucorales मा चौडा र कम septa भएका hyphae हुन्छन्।","explanationNe":"Mucorales मा चौडा र कम septa भएका hyphae हुन्छन्।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
('bmlt-mycovirology1-practice-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"Which fungi primarily infect keratinized tissues such as skin, hair and nails?","translation":"","options":["Dermatophytes","Cryptococcus","Pneumocystis","Histoplasma"],"correctIndex":0,"explanation":"Dermatophytes utilize keratin and cause superficial infections. नेपाली: Dermatophytes ले छाला, कपाल र नङमा संक्रमण गर्छन्।","explanationNe":"Dermatophytes ले छाला, कपाल र नङमा संक्रमण गर्छन्।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
('bmlt-mycovirology1-practice-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"Which test is used to detect fungal elements directly in skin scrapings?","translation":"","options":["10% KOH mount","Widal test","Coagulase test","Benedict test"],"correctIndex":0,"explanation":"KOH clears keratin and helps visualize fungal hyphae. नेपाली: छालाको scraping मा KOH mount ले fungus देखाउँछ।","explanationNe":"छालाको scraping मा KOH mount ले fungus देखाउँछ।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
('bmlt-mycovirology1-practice-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"Which organism is classically associated with dimorphism, growing as mold at room temperature and yeast in tissue?","translation":"","options":["Histoplasma capsulatum","Candida albicans","Cryptococcus neoformans","Trichophyton mentagrophytes"],"correctIndex":0,"explanation":"Histoplasma is thermally dimorphic. नेपाली: Histoplasma तापक्रमअनुसार mold र yeast रूप देखाउँछ।","explanationNe":"Histoplasma तापक्रमअनुसार mold र yeast रूप देखाउँछ।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
('bmlt-mycovirology1-practice-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"Which specimen is appropriate for suspected dermatophytosis of the scalp?","translation":"","options":["Hair and scalp scales from the active lesion","Saliva only","Urine only","CSF"],"correctIndex":0,"explanation":"Collect affected hairs and scales from the lesion margin. नेपाली: टाउकोको दादमा प्रभावित कपाल र छालाको scale लिनुपर्छ।","explanationNe":"टाउकोको दादमा प्रभावित कपाल र छालाको scale लिनुपर्छ।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
('bmlt-mycovirology1-practice-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"Which virus is a major cause of infectious mononucleosis?","translation":"","options":["Epstein–Barr virus","Rotavirus","Rabies virus","Norovirus"],"correctIndex":0,"explanation":"EBV infects B lymphocytes and is associated with infectious mononucleosis. नेपाली: EBV infectious mononucleosis को प्रमुख कारण हो।","explanationNe":"EBV infectious mononucleosis को प्रमुख कारण हो।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
('bmlt-mycovirology1-practice-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"Which viral genome is found in HIV?","translation":"","options":["RNA","Double-stranded DNA","Single-stranded DNA","No nucleic acid"],"correctIndex":0,"explanation":"HIV is an enveloped retrovirus with two copies of single-stranded RNA. नेपाली: HIV मा RNA genome हुन्छ।","explanationNe":"HIV मा RNA genome हुन्छ।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
('bmlt-mycovirology1-practice-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"Which enzyme allows retroviruses to synthesize DNA from RNA?","translation":"","options":["Reverse transcriptase","DNA ligase","Catalase","Coagulase"],"correctIndex":0,"explanation":"Reverse transcriptase converts viral RNA into DNA. नेपाली: Reverse transcriptase ले RNA बाट DNA बनाउँछ।","explanationNe":"Reverse transcriptase ले RNA बाट DNA बनाउँछ।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
('bmlt-mycovirology1-practice-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"Which hepatitis virus is primarily transmitted by the fecal–oral route?","translation":"","options":["HAV","HBV","HCV","HDV"],"correctIndex":0,"explanation":"Hepatitis A is commonly transmitted through contaminated food or water. नेपाली: Hepatitis A दूषित खाना/पानीबाट सर्छ।","explanationNe":"Hepatitis A दूषित खाना/पानीबाट सर्छ।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
