('bmlt-mycovirology1-practice-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"Which marker generally indicates current hepatitis B infection?","translation":"","options":["HBsAg","Anti-HBs only","Anti-HAV IgG","Anti-HCV only"],"correctIndex":0,"explanation":"HBsAg indicates current HBV infection, though full interpretation uses a marker panel. नेपाली: HBsAg positive हुँदा हालको HBV infection हुन सक्छ।","explanationNe":"HBsAg positive हुँदा हालको HBV infection हुन सक्छ।","topic":"Clinical Mycology & Virology"}'::jsonb,true),
